import { useState } from 'react';
import type { CSSProperties } from 'react';

// Acme DS has no Switch/Toggle component yet, so this is built from a native
// checkbox (role="switch") styled with Acme tokens only (no raw colors,
// spacing from the --space-* scale).

type SettingKey = 'emailDigests' | 'pushAlerts' | 'productAnnouncements';

const SETTINGS: { key: SettingKey; label: string; description: string }[] = [
  {
    key: 'emailDigests',
    label: 'Email digests',
    description: 'A summary of activity sent to your inbox.',
  },
  {
    key: 'pushAlerts',
    label: 'Push alerts',
    description: 'Instant notifications on your devices.',
  },
  {
    key: 'productAnnouncements',
    label: 'Product announcements',
    description: 'News about new features and updates.',
  },
];

const styles: Record<string, CSSProperties> = {
  section: {
    display: 'flex',
    flexDirection: 'column',
    gap: 'var(--space-4)',
    padding: 'var(--space-5)',
    background: 'var(--color-surface-default)',
    color: 'var(--color-text-primary)',
    maxWidth: 560,
  },
  heading: { margin: 0 },
  list: {
    listStyle: 'none',
    margin: 0,
    padding: 0,
    display: 'flex',
    flexDirection: 'column',
    gap: 'var(--space-4)',
  },
  row: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    gap: 'var(--space-4)',
  },
  text: { display: 'flex', flexDirection: 'column', gap: 'var(--space-1)' },
  description: { color: 'var(--color-text-secondary)' },
  track: {
    position: 'relative',
    flexShrink: 0,
    width: 'var(--space-7)',
    height: 'var(--space-5)',
    borderRadius: 'var(--space-5)',
    cursor: 'pointer',
    transition: 'background 120ms',
  },
  thumb: {
    position: 'absolute',
    top: 'var(--space-1)',
    width: 'var(--space-4)',
    height: 'var(--space-4)',
    borderRadius: '50%',
    background: 'var(--color-surface-default)',
    transition: 'left 120ms',
  },
  input: {
    position: 'absolute',
    inset: 0,
    width: '100%',
    height: '100%',
    margin: 0,
    opacity: 0,
    cursor: 'pointer',
  },
};

export function TaskScreen() {
  // Each change applies immediately; there is no save step.
  const [values, setValues] = useState<Record<SettingKey, boolean>>({
    emailDigests: true,
    pushAlerts: true,
    productAnnouncements: false,
  });

  const toggle = (key: SettingKey, next: boolean) =>
    setValues((prev) => ({ ...prev, [key]: next }));

  return (
    <section aria-labelledby="notif-heading" style={styles.section}>
      <h2 id="notif-heading" style={styles.heading}>
        Notification preferences
      </h2>
      <ul style={styles.list}>
        {SETTINGS.map(({ key, label, description }) => {
          const on = values[key];
          const labelId = `${key}-label`;
          const descId = `${key}-desc`;
          return (
            <li key={key} style={styles.row}>
              <div style={styles.text}>
                <span id={labelId}>{label}</span>
                <span id={descId} style={styles.description}>
                  {description}
                </span>
              </div>
              <span
                style={{
                  ...styles.track,
                  background: on
                    ? 'var(--color-action-primary)'
                    : 'var(--color-surface-subtle)',
                  outline: on ? 'none' : '1px solid var(--color-text-disabled)',
                }}
              >
                <input
                  type="checkbox"
                  role="switch"
                  checked={on}
                  aria-labelledby={labelId}
                  aria-describedby={descId}
                  onChange={(e) => toggle(key, e.target.checked)}
                  style={styles.input}
                />
                <span
                  aria-hidden="true"
                  style={{
                    ...styles.thumb,
                    left: on ? 'var(--space-5)' : 'var(--space-1)',
                    background: on
                      ? 'var(--color-text-inverse)'
                      : 'var(--color-text-disabled)',
                  }}
                />
              </span>
            </li>
          );
        })}
      </ul>
    </section>
  );
}

